import { TriggerDefinition } from '../../TriggerDefinition'
import { DateTimeColumn, ReferenceColumn, TableNameColumn } from '../../../db'

export const knowledgeManagementTrigger = TriggerDefinition({
    $id: '9bdb2c0483331210730e5b43c22bc071',
    name: 'Knowledge Management',
    type: 'knowledge_management',
    outputs: {
        run_start_date_time: DateTimeColumn({
            label: 'Run Start Date Time',
        }),
        knowledge: ReferenceColumn({
            label: 'Knowledge',
            referenceTable: 'kb_knowledge',
            mandatory: true,
        }),
        run_start_time: DateTimeColumn({
            label: 'Run Start Time',
        }),
        table_name: TableNameColumn({
            label: 'Table Name',
            default: 'kb_knowledge',
        }),
    },
})
